/**
 * Fetch/patch one issue over JSON.
 *
 * Owner D. The tenant check is explicit here rather than implied: the route
 * takes an `issueId` straight off the URL, so `assertOrgScope()` against the
 * fetched row is what stops one organization reading another's issue by id.
 *
 * Must call (do not reimplement): can, assertOrgScope
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { can } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import { issueIdSchema } from "@/schemas/common";
import { updateIssueSchema } from "@/schemas/issue";
import { getIssue, updateIssue } from "@/server/services/issue-service";

export const dynamic = "force-dynamic";

type RouteContext = { params: Promise<{ issueId: string }> };

export async function GET(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { issueId } = await context.params;
    const parsedId = issueIdSchema.safeParse(issueId);
    if (!parsedId.success) {
      return failure("validation_failed", "Malformed issue id.");
    }

    const actor = await getActor(orgSlug);
    const found = await getIssue(actor, actor.orgId, parsedId.data);
    assertOrgScope(actor, found.issue.orgId);

    const allowed = can(actor, "issue:read", {
      kind: "issue",
      orgId: found.issue.orgId,
      projectId: found.issue.projectId,
      issueId: found.issue.id,
      authorId: found.issue.authorId,
      assigneeId: found.issue.assigneeId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot read this issue.");
    }

    return Response.json(found);
  } catch (error) {
    return errorResponse(error);
  }
}

export async function PATCH(
  request: Request,
  context: RouteContext,
): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    if (orgSlug === null) {
      return failure("validation_failed", "orgSlug is required.");
    }

    // Next.js 16: route `params` is a Promise and MUST be awaited.
    const { issueId } = await context.params;
    const actor = await getActor(orgSlug);

    const body: unknown = await request.json();
    const parsed = updateIssueSchema.safeParse({
      ...(typeof body === "object" && body !== null ? body : {}),
      orgId: actor.orgId,
      issueId,
    });
    if (!parsed.success) {
      return failure("validation_failed", "Bad issue patch.");
    }

    const current = await getIssue(actor, actor.orgId, parsed.data.issueId);
    assertOrgScope(actor, current.issue.orgId);

    const allowed = can(actor, "issue:update", {
      kind: "issue",
      orgId: current.issue.orgId,
      projectId: current.issue.projectId,
      issueId: current.issue.id,
      authorId: current.issue.authorId,
      assigneeId: current.issue.assigneeId,
    });
    if (!allowed) {
      return failure("forbidden", "You cannot update this issue.");
    }

    const updated = await updateIssue(actor, parsed.data);
    return Response.json(updated);
  } catch (error) {
    return errorResponse(error);
  }
}
/**
 * Receives third-party callbacks validated with `inboundWebhookSchema`.
 *
 * Owner D. The receiver is deliberately dumb: it validates the envelope, charges
 * a rate limit and hands the payload to the event bus. Anything that needs to
 * happen as a result is a subscriber's job, so a slow handler cannot make the
 * sender time out and retry.
 *
 * Must call (do not reimplement): inboundWebhookSchema, consumeRateLimit
 */

import { ANONYMOUS_ORG_ID } from "@/actions/_lib/permission-resources";
import { errorResponse, failure } from "@/app/api/_lib/responses";
import { emit } from "@/lib/event-bus";
import { consumeRateLimit } from "@/lib/rate-limit";
import { inboundWebhookSchema } from "@/schemas/webhook";
import { toIsoTimestamp } from "@/types/common";

export const dynamic = "force-dynamic";

const INBOUND_BUCKET = "webhook:inbound";

export async function POST(request: Request): Promise<Response> {
  try {
    // The sender is not a tenant, so the bucket is the shared anonymous one.
    const verdict = await consumeRateLimit(ANONYMOUS_ORG_ID, INBOUND_BUCKET);
    if (!verdict.allowed) {
      return failure("rate_limited", "Too many inbound callbacks.");
    }

    const body: unknown = await request.json();
    const parsed = inboundWebhookSchema.safeParse(body);
    if (!parsed.success) {
      return failure("validation_failed", "Unrecognised callback envelope.");
    }

    await emit("webhook.delivery_requested", {
      orgId: ANONYMOUS_ORG_ID,
      actorId: null,
      occurredAt: toIsoTimestamp(parsed.data.occurredAt),
      eventType: `inbound.${parsed.data.source}`,
      payload: parsed.data.payload,
    });

    // 202: the callback is accepted, not yet acted on.
    return Response.json({ accepted: true, eventId: parsed.data.eventId }, { status: 202 });
  } catch (error) {
    return errorResponse(error);
  }
}
/** Domain-error to `AppErrorShape` mapping for every error class. */
import { describe, expect, it } from "vitest";
import { z } from "zod";
import {
  HTTP_STATUS_BY_CODE,
  fieldErrorsFromZod,
  isDomainError,
  toActionResult,
  toAppError,
} from "@/lib/errors";
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError, explain } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { OrgId } from "@/types/common";
import { makeActor, ORG_A, ORG_B } from "../helpers/factories";

const schema = z.object({
  title: z.string().min(3),
  estimate: z.number().int(),
});

function permissionError(): PermissionDeniedError {
  const actor = makeActor({ role: "viewer" });
  const resource = { kind: "organization", orgId: ORG_A } as const;
  return new PermissionDeniedError("org:delete", explain(actor, "org:delete", resource));
}

describe("lib/errors", () => {
  it("maps a permission denial to `forbidden` with the decision in meta", () => {
    const shape = toAppError(permissionError());
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.action).toBe("org:delete");
    expect(shape.meta?.reason).toBe("denied_by_role");
  });

  it("maps a tenant scope violation to `tenant_scope_violation`", () => {
    const shape = toAppError(new TenantScopeError(ORG_A, ORG_B));
    expect(shape.code).toBe("tenant_scope_violation");
    expect(shape.meta?.expectedOrgId).toBe(ORG_A);
    expect(shape.message).not.toContain(ORG_B as string);
  });

  it("maps a disabled feature to `forbidden` and names the flag", () => {
    const shape = toAppError(new FeatureDisabledError("webhooks"));
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.flag).toBe("webhooks");
  });

  it("maps double archiving to `conflict`", () => {
    const shape = toAppError(new AlreadyArchivedError("Issue", "01ISS"));
    expect(shape.code).toBe("conflict");
    expect(shape.meta?.entity).toBe("Issue");
  });

  it("maps an invalid slug to `validation_failed` with a slug field error", () => {
    const shape = toAppError(new InvalidSlugError("Admin!", "is reserved"));
    expect(shape.code).toBe("validation_failed");
    expect(shape.fieldErrors?.slug?.[0]).toContain("is reserved");
  });

  it("maps a ZodError to field errors keyed by dotted path", () => {
    const parsed = schema.safeParse({ title: "no", estimate: 1.5 });
    expect(parsed.success).toBe(false);
    if (parsed.success) return;

    const fields = fieldErrorsFromZod(parsed.error);
    expect(Object.keys(fields).sort()).toEqual(["estimate", "title"]);
    expect(toAppError(parsed.error).code).toBe("validation_failed");
  });

  it("falls back to `internal_error` for an unknown throw", () => {
    expect(toAppError(new Error("boom")).code).toBe("internal_error");
    expect(toAppError("boom").code).toBe("internal_error");
    expect(toAppError("boom").message).toContain("Something went wrong");
  });

  it("recognises exactly the domain error classes", () => {
    expect(isDomainError(permissionError())).toBe(true);
    expect(isDomainError(new TenantScopeError(ORG_A, ORG_B))).toBe(true);
    expect(isDomainError(new InvalidSlugError("x", "too short"))).toBe(true);
    expect(isDomainError(new Error("boom"))).toBe(false);
    expect(isDomainError(null)).toBe(false);
  });

  it("gives every error code an HTTP status", () => {
    for (const [code, status] of Object.entries(HTTP_STATUS_BY_CODE)) {
      expect(status, code).toBeGreaterThanOrEqual(400);
    }
    expect(HTTP_STATUS_BY_CODE.rate_limited).toBe(429);
    expect(HTTP_STATUS_BY_CODE.plan_limit_exceeded).toBe(402);
  });

  it("wraps a failure as an ActionResult, never throwing", () => {
    const result = toActionResult(new AlreadyArchivedError("Project", "01PRJ"));
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.error.code).toBe("conflict");
    expect(typeof result.submittedAt).toBe("string");
  });

  it("keeps a cross-tenant org id out of the user-facing message", () => {
    const other = "01HZZZDDDDDDDDDDDDDDDDDDDD" as OrgId;
    expect(toAppError(new TenantScopeError(ORG_A, other)).message).toBe(
      "That resource belongs to a different organization.",
    );
  });
});
