"use client";

/**
 * Assignee combobox restricted to active members.
 */
import { Combobox, type ComboboxOption } from "@/components/ui/combobox";
import { isLive } from "@/lib/soft-delete";
import type { UserId } from "@/types/common";
import type { MemberWithUser } from "@/types/member";
import type { ReactElement } from "react";

export type IssueAssigneePickerProps = {
  value: UserId | null;
  members: readonly MemberWithUser[];
  disabled?: boolean;
  onChange: (userId: UserId | null) => void;
};

/**
 * Only members who can actually act in the org are offered: an invited member
 * has not accepted yet and a suspended one must not receive new work. Removed
 * members are soft-deleted, so `isLive()` decides that part.
 */
export function assignableMembers(
  members: readonly MemberWithUser[],
): readonly MemberWithUser[] {
  return members.filter(
    (member) => member.status === "active" && isLive(member),
  );
}

export function IssueAssigneePicker(
  props: IssueAssigneePickerProps,
): ReactElement | null {
  const options: readonly ComboboxOption[] = assignableMembers(
    props.members,
  ).map((member) => ({
    value: member.userId,
    label: member.user.name,
    description: member.user.email,
  }));

  return (
    <Combobox
      value={props.value}
      options={options}
      placeholder={props.disabled === true ? "Assignee locked" : "Unassigned"}
      emptyLabel="No assignable members"
      onChange={(value) => props.onChange(value as UserId | null)}
    />
  );
}
/**
 * The typing-side half of @-mentions.
 *
 * `@/lib/mentions` owns what a finished comment body *means* (which users it
 * mentions); this module owns what the caret is currently doing — where the
 * active `@token` starts, what it filters to, and what the body looks like
 * once a suggestion is accepted. Splitting it that way keeps the textarea from
 * re-deriving the parsing rules the server also applies.
 */
import type { MemberWithUser } from "@/types/member";

/** An in-progress mention: `@` plus the characters typed after it. */
export interface MentionQuery {
  /** Index of the `@` in the body. */
  readonly start: number;
  /** Index just past the last typed character. */
  readonly end: number;
  /** The text after `@`, lowercased for matching. */
  readonly query: string;
}

const MENTION_CHARS = /^[a-zA-Z0-9._-]*$/;

/**
 * Finds the mention the caret sits inside, or `null` when the caret is not in
 * one. A mention only starts at the beginning of the body or after
 * whitespace, so an email address never opens the autocomplete.
 */
export function findMentionQuery(
  body: string,
  caret: number,
): MentionQuery | null {
  const upTo = body.slice(0, Math.max(0, Math.min(caret, body.length)));
  const at = upTo.lastIndexOf("@");
  if (at === -1) return null;

  const before = at === 0 ? "" : upTo[at - 1] ?? "";
  if (before.length > 0 && !/\s/.test(before)) return null;

  const typed = upTo.slice(at + 1);
  if (!MENTION_CHARS.test(typed)) return null;

  return { start: at, end: upTo.length, query: typed.toLowerCase() };
}

/** The handle Taskflow mentions people by: the local part of their email. */
export function mentionHandle(member: MemberWithUser): string {
  const [local = member.user.name] = member.user.email.split("@");
  return local.toLowerCase();
}

/** Members whose handle or display name matches the in-progress query. */
export function matchMembers(
  members: readonly MemberWithUser[],
  query: string,
  limit = 5,
): readonly MemberWithUser[] {
  const needle = query.toLowerCase();
  const matches =
    needle.length === 0
      ? members
      : members.filter(
          (member) =>
            mentionHandle(member).includes(needle) ||
            member.user.name.toLowerCase().includes(needle),
        );
  return matches.slice(0, limit);
}

/** Replaces the in-progress mention with the chosen member's handle. */
export function applyMention(
  body: string,
  mention: MentionQuery,
  member: MemberWithUser,
): { body: string; caret: number } {
  const inserted = `@${mentionHandle(member)} `;
  const next = body.slice(0, mention.start) + inserted + body.slice(mention.end);
  return { body: next, caret: mention.start + inserted.length };
}
"use client";

/**
 * Comment box bound to `createCommentSchema`.
 *
 * Must call (do not reimplement): createCommentSchema
 */
import { useState } from "react";
import { Button } from "@/components/ui/button";
import { ErrorMessage } from "@/components/ui/error-message";
import { useFormAction } from "@/hooks/use-form-action";
import { createCommentSchema, type CreateCommentInput } from "@/schemas/comment";
import type { ActionResult } from "@/types/api";
import type { CommentId, IssueId, OrgId, UserId } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { MemberWithUser } from "@/types/member";
import type { ReactElement } from "react";
import { MentionTextarea } from "./mention-textarea";

export type CommentComposerProps = {
  orgId: OrgId;
  issueId: IssueId;
  members: readonly MemberWithUser[];
  onSubmit: (input: CreateCommentInput) => Promise<ActionResult<Comment>>;
  /** Set when replying inside a thread rather than starting a new one. */
  parentId?: CommentId | null;
};

export function CommentComposer(
  props: CommentComposerProps,
): ReactElement | null {
  const { orgId, issueId, members, onSubmit, parentId = null } = props;

  const [body, setBody] = useState("");
  const [mentioned, setMentioned] = useState<readonly UserId[]>([]);
  const [invalid, setInvalid] = useState<string | null>(null);

  const { submit, pending, error } = useFormAction(onSubmit, {
    onSuccess: () => {
      setBody("");
      setMentioned([]);
    },
  });

  async function handleSubmit(): Promise<void> {
    // Parse with the same schema the Server Action re-parses, so the button
    // never posts something the server is going to reject for shape.
    const parsed = createCommentSchema.safeParse({
      orgId,
      issueId,
      body,
      parentId,
      mentionedUserIds: mentioned,
    });

    if (!parsed.success) {
      setInvalid(parsed.error.issues[0]?.message ?? "This comment is not valid");
      return;
    }

    setInvalid(null);
    await submit(parsed.data);
  }

  return (
    <div className="comment-composer space-y-2">
      <MentionTextarea
        value={body}
        members={members}
        onChange={(nextBody, nextMentions) => {
          setBody(nextBody);
          setMentioned(nextMentions);
        }}
      />

      <ErrorMessage message={invalid ?? error?.message ?? null} />

      <div className="flex items-center justify-between">
        <span className="text-xs text-neutral-500">
          {mentioned.length > 0
      limit: 25,
      cursor: null,
    });
    expect(page.items).toHaveLength(1);
  });

  // Notifications carry the org id and are only visible inside that tenant.
  it("scopes notifications to the recipient's organization", async () => {
    const other = await createTenant("notify-other", "growth");

    await notify(tenant.org.id, "member_joined", [tenant.userIds.owner], {
      title: "Member joined",
      body: "Welcome",
      href: "/settings/members",
      actorId: null,
    });

    await expect(
      listNotifications(other.actors.owner, {
        orgId: tenant.org.id,
        recipientId: tenant.userIds.owner,
        unreadOnly: false,
        limit: 25,
        cursor: null,
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    const own = await listNotifications(tenant.actors.owner, {
      orgId: tenant.org.id,
      recipientId: tenant.userIds.owner,
      unreadOnly: false,
      limit: 25,
      cursor: null,
    });
    expect(own.total).toBeGreaterThanOrEqual(1);
  });
});
