/**
 * Guards for the ids a write *points at* — an assignee, a project lead, a
 * label set, a parent issue, a parent comment.
 *
 * `assertOrgScope()` only vets the organization a payload names for itself;
 * these vet everything else the payload references, and every service calls
 * them before its first write so a refused change changes nothing:
 *
 *  - a reference owned by another organization is a `TenantScopeError`, the
 *    same refusal as any other cross-tenant access;
 *  - a reference that does not exist, is archived, or is not usable from where
 *    the change is made is a `NotFoundError`.
 *
 * Must call (do not reimplement): assertOrgScope, isArchived
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor, Member, MemberWithUser } from "@/types/member";

/** Page size used when walking the whole member list. */
const MEMBER_PAGE_SIZE = 100;

/**
 * A *current* member can act in the organization today: the membership is
 * live (a removed member is archived) and active (an invited member has not
 * accepted yet, a suspended one must not receive new work). The same rule the
 * assignee picker applies client-side.
 */
function isCurrent(member: Member): boolean {
  return member.status === "active" && !isArchived(member);
}

/** True when `userId` is a current member of `orgId`. */
export async function isCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<boolean> {
  const member = await memberRepo.findMember(orgId, userId);
  return member !== null && isCurrent(member);
}

/**
 * Throws `NotFoundError` unless `userId` is a current member of `orgId`.
 * Users are global rows, so "a stranger" and "someone who left" are the same
 * answer here: there is no such member in this organization.
 */
export async function requireCurrentMember(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  if (!(await isCurrentMember(orgId, userId))) {
    throw new NotFoundError("Member", userId);
  }
}

/** Every current member of `orgId`, however many pages that takes. */
export async function listCurrentMembers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const members: MemberWithUser[] = [];
  let cursor: string | null = null;

  for (;;) {
    const page = await memberRepo.listMembers({
      orgId,
      status: "active",
      limit: MEMBER_PAGE_SIZE,
      cursor,
    });
    members.push(...page.items.filter(isCurrent));

    if (page.nextCursor === null || page.items.length === 0) break;
    cursor = page.nextCursor;
  }

  return members;
}

/**
 * Validates a label set against the organization's own labels and returns it
 * de-duplicated, in the caller's order. A label owned by another organization
 * is a tenant-scope violation; one that exists nowhere is not found. Scope is
 * judged for the whole set first, so a mixed set fails as cross-tenant.
 */
export async function requireOwnLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<readonly LabelId[]> {
  const unique = [...new Set(labelIds)];
  if (unique.length === 0) return unique;

  const owners = await labelRepo.findLabelOwners(unique);

  for (const labelId of unique) {
    const owner = owners.get(labelId);
    if (owner !== undefined && owner !== orgId) assertOrgScope(actor, owner);
  }
  for (const labelId of unique) {
    if (owners.get(labelId) !== orgId) throw new NotFoundError("Label", labelId);
  }

  return unique;
}

/**
 * Loads the issue a write references. Returns `null` when it exists nowhere,
 * and throws `TenantScopeError` when it exists in another organization — the
 * caller decides what "usable" means for a row that is in scope.
 */
export async function findReferencedIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue | null> {
  const issue = await issueRepo.findIssueById(orgId, issueId);
  if (issue !== null) return issue;

  const owner = await issueRepo.findIssueOwner(issueId);
  if (owner !== null && owner !== orgId) assertOrgScope(actor, owner);
  return null;
}

/**
 * A parent issue must be a live issue of the same project: anything else
 * could not be seen from where the sub-issue lives.
 */
export function requireParentIssue(
  parent: Issue | null,
  projectId: ProjectId,
  parentId: IssueId,
): Issue {
  if (
    parent === null ||
    parent.projectId !== projectId ||
    isArchived(parent)
  ) {
    throw new NotFoundError("Issue", parentId);
  }
  return parent;
}

/**
 * A reply must name a live, top-level comment on the same issue. A parent in
 * another organization is a tenant-scope violation; a missing or deleted
 * parent, a parent on a different issue and a reply-to-a-reply are not found —
 * none of them would ever render in this issue's thread.
 */
export async function requireReplyParent(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = await commentRepo.findCommentById(orgId, parentId);

  if (parent === null) {
    const owner = await commentRepo.findCommentOwner(parentId);
    if (owner !== null && owner !== orgId) assertOrgScope(actor, owner);
    throw new NotFoundError("Comment", parentId);
  }

  if (
    parent.issueId !== issueId ||
    parent.parentId !== null ||
    isArchived(parent)
  ) {
    throw new NotFoundError("Comment", parentId);
  }

  return parent;
}

