    expect(after.issue.title).toBe("Ship the thing");
    expect(after.labels.map((l) => l.id)).toEqual([own.id]);

    // stale join row attached before
    getDb().insert(issueLabels).values({ orgId: a.org.id, issueId: issue.id, labelId: foreign.id }).run();
