      await expect(projectService.createProject(a.actors.admin, { orgId: a.org.id, name: "Lead test", slug: "lead-test", key: "LT", description: null, visibility: "org", leadId: who, color: "#6366f1", targetDate: null })).rejects.toBeInstanceOf(NotFoundError);
      await expect(projectService.updateProject(a.actors.admin, { orgId: a.org.id, projectId: a.project.id, leadId: who })).rejects.toBeInstanceOf(NotFoundError);
    }
    expect(events).toEqual([]);
    expect((await issueRepo.findIssueById(a.org.id, issue.id))?.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(a.org.id, a.project.id))?.leadId).toBe(a.userIds.owner);
    expect(await projectRepo.findProjectBySlug(a.org.id, "lead-test")).toBeNull();

    const ok = await issueService.assignIssue(a.actors.member, { orgId: a.org.id, issueId: issue.id, assigneeId: a.userIds.admin });
    expect(ok.assigneeId).toBe(a.userIds.admin);
    await projectService.updateProject(a.actors.admin, { orgId: a.org.id, projectId: a.project.id, leadId: a.userIds.admin });

    // mentions
    const c = await commentService.createComment(a.actors.member, { orgId: a.org.id, issueId: issue.id, body: "hi @leaver and @owner", parentId: null, mentionedUserIds: [leaver.id, stranger.id, b.userIds.owner, a.userIds.viewer] });
